　佐切の隣。ここが、今の自分の生きたいところ。私が私らしく居られるところ。たとえ本人に迷惑がられても変わらない。それほどの決意を、再会するまでの歩みとともに固めてきたはず。だから今さら動じるのは気のせいに決まっている。
「杠さん」
