　川沿いをひたすら歩く。周囲のタオの動きにばかり集中していた私は、隣の佐切のそれが乱れていることにようやく気づいた。タオは、何かを葛藤している時などに乱れる。私が声をかける前に「あの、」佐切が口を開いた。
