　春の陽射しはやわらかく降りそそぎ、てっぺんに昇ると、傾いていきました。
　その夜、杠は佐切を求めました。日がな一日ぼんやりとしている佐切に、もはやなにも考えさせまいとしたのでしょう。初めはあまり気乗りしないらしかった佐切も、考え直したのか杠の体に指先を滑らせていき、その後ふたりはひたすらに求め合いました。
