「妖怪」という言葉は本来、人の理解を超える不可思議な現象や、それを引きおこす存在のことを指すものであった。
　妖怪は、ずっと、ずっとむかしから在った。暇を持てあまして寝そべり、いつしか山となった者。各地を飛びまわることを好み、やがて風となった者。王朝の世を揺るがした大妖怪の、末裔という者も居る。
　人々は彼らを畏れ、ときに祀った。とりわけ強い力をもつ妖怪は、各地の寺社において丁重に扱われることもあった。祟りをしずめ、災いから自分たちを守ってもらうためである。
　そして時代が進み、彼らのことは口伝えに語りつがれていく。さらには絵に描かれ、文書に記され、人々のあいだで広く共有されていった。まるで、人間たちの想像から生み出されたものであるかのように。
　ところがもうひとつ時代が進むと、妖怪にまつわる思想は「迷信」あるいは「旧弊」と位置づけられ、しだいに抑圧される対象となっていく。妖怪は祀られるようなものではなく、退治されるべきものだ、と。
　そうして人々の信心や畏れが薄まるにつれ、彼らは息づく範囲をしずかに縮小していったのであった……。



　これは、とある山の奥にひっそりと暮らす、妖怪ふたりの話である。





