　おだやかな表情をたたえた瀬戸内の海。遠くに見える島々の名は知らないが、行き交う船とあわせて、私はしばらくぼうっとそれらを眺めた。そうしながら、繰り返す波の音を聞いているうちに、なんだか眠たくなってきた。
　いい天気だから日なたぼっこでもしようかな。そう思いついた私は、その辺にあった屋敷の裏手に回り、周囲に誰もいないことをしっかり確認してから、ひょいひょいっと跳んでその屋根の上に登った。ここならちょうどいい。さっそく仰向けに寝転がって目を閉じると、じわじわと、貴重な冬の陽が体にやさしく染み渡っていくのを感じられた。
