　あーあ。これで何度目やろ。いつも通り池のほとりにたたずんで、うなだれる。親から借りてきた渋柿色の傘が重たく感じ、それを右の肩にもたせ掛ける。後ろのほうでいくつもしずくが流れ落ちていった。
