　うちは傘をなかば深くして、彼女たちの会話を聞くとは無しに聞いてみる。小気味よく生まれるひとこと、ふたこと。こぼれる笑み。その仲の良さげな様子の微笑ましさからだろうか。ここを侵されたという気持ちにはまったくならなかった。あっちも、うちのことを邪魔だとは思っていない気がする。お互いに居場所を探しにきているような、そんな親近感があった。
